const rawResponse = $json.text || '';

let resumeData;

try {
  let cleaned = rawResponse.trim();

  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');

  if (s !== -1 && e !== -1) {
    cleaned = cleaned.substring(s, e + 1);
  }

  resumeData = JSON.parse(cleaned);

} catch (err) {

  throw new Error(
    'Failed to parse resume AI JSON: ' +
    err.message
  );
}

// Retrieve preferences dynamically from Load Resume & Preferences node
let resumePrefs = {};
try {
  resumePrefs = $("Load Resume & Preferences").first().json.userPreferences || {};
} catch (e) {
  console.log("Failed to retrieve preferences from prior node, using defaults", e.message);
}

const prefs = {
  locations: resumePrefs.locations || ['Remote', 'Gurgaon', 'Bengaluru', 'Hyderabad'],
  jobType: resumePrefs.jobType || ['Full-time', 'Internship'],
  platforms: resumePrefs.platforms || ['remotive', 'internshala', 'unstop', 'arbeitnow', 'remoteok', 'himalayas', 'themuse']
};

const search = resumeData.search || {};

const suggestedTitles =
search.suggested_titles || [];

const finalTitles =
suggestedTitles.length > 0
? suggestedTitles
: [
    resumeData.professional?.current_title ||
    'Software Engineer'
  ];

const seniority =
resumeData.professional?.seniority ||
'intern';

const primaryQuery =
finalTitles[0];

const skillQuery =
(resumeData.skills?.technical || [])
.slice(0,5)
.join(' OR ');

const locationParam =
prefs.locations[0];

return [{
  json: {
    resumeData,
    userPreferences: prefs,

    searchConfig: {
      titles: finalTitles,
      keywords: search.keywords || [],
      locations: prefs.locations,
      primaryQuery,
      skillQuery,
      locationParam,
      seniority,

      experienceYears:
      resumeData.professional?.years_experience || 0,

      domain:
      resumeData.professional?.domain || '',

      salaryRange:
      search.salary_range || {},

      jobType:
      prefs.jobType,

      platforms:
      prefs.platforms
    },

    requestId:
    'job-' + Date.now()
  }
}];

// Output one item per platform so each scraper runs independently
const config = $input.first().json;
const platforms = config.searchConfig.platforms;

return platforms.map(platform => ({
  json: { ...config, currentPlatform: platform }
}));

// Normalize raw API response into unified job schema
// $json is the raw API response. $json.currentPlatform tells us which platform.
const platform = $json.currentPlatform || 'unknown';
const searchConfig = $json.searchConfig || {};
const raw = $json; // full input item including API response fields

const allJobs = [];

try {
  if (platform === 'remotive') {
    // Remotive free API — returns jobs[]
    const jobs = raw.jobs || [];
    jobs.forEach(j => allJobs.push({
      platform: 'Remotive',
      id: String(j.id) || ('rm-' + Math.random()),
      title: j.title || '',
      company: j.company_name || '',
      location: j.candidate_required_location || 'Remote',
      description: (j.description || '').replace(/<[^>]+>/g, '').substring(0, 800),
      url: j.url || '',
      salary: j.salary || '',
      posted_date: j.publication_date || '',
      job_type: j.job_type || 'Full-time',
      remote: true,
      company_logo: j.company_logo_url || '',
      applicants: null,
      seniority: '',
      required_skills: j.tags || [],
      highlights: {}
    }));
  }

  else if (platform === 'jobicy') {
    const jobs = raw.jobs || [];
    jobs.forEach(j => allJobs.push({
      platform: 'Jobicy',
      id: String(j.id) || ('jb-' + Math.random()),
      title: j.jobTitle || '',
      company: j.companyName || '',
      location: j.jobGeo || 'Remote',
      description: (j.jobExcerpt || j.jobDescription || '').replace(/<[^>]+>/g, '').substring(0, 800),
      url: j.url || '',
      salary: j.salaryMin ? `$${j.salaryMin}–$${j.salaryMax}` : '',
      posted_date: j.pubDate || '',
      job_type: j.jobType || 'Full-time',
      remote: true,
      company_logo: j.companyLogo || '',
      applicants: null,
      seniority: j.jobLevel || '',
      required_skills: [],
      highlights: {}
    }));
  }

  else if (platform === 'unstop') {
    const items = raw.data?.data || raw.data || [];
    items.forEach(j => {
      const opp = j.opportunity || j;
      allJobs.push({
        platform: 'Unstop',
        id: opp.id || ('un-' + Math.random()),
        title: opp.title || '',
        company: opp.organisation?.name || opp.company_name || '',
        location: opp.organisation?.city || opp.city || 'India',
        description: opp.description || opp.extra_detail || '',
        url: `https://unstop.com/jobs/${opp.id}-${opp.public_url || ''}`,
        salary: opp.salary || opp.stipend || '',
        posted_date: opp.start || '',
        job_type: opp.type || 'Full-time',
        remote: (opp.type_meta || '').toLowerCase().includes('remote'),
        company_logo: opp.organisation?.logo_url || '',
        applicants: opp.registered_count || null,
        seniority: '',
        required_skills: [],
        highlights: {}
      });
    });
  }

  else if (platform === 'arbeitnow') {
    const jobs = raw.data || [];
    jobs.forEach(j => allJobs.push({
      platform: 'Arbeitnow',
      id: j.slug || ('an-' + Math.random()),
      title: j.title || '',
      company: j.company_name || '',
      location: j.location || 'Europe',
      description: (j.description || '').substring(0, 800),
      url: j.url || '',
      salary: '',
      posted_date: j.created_at ? new Date(j.created_at * 1000).toISOString() : '',
      job_type: (j.job_types || []).join(', ') || 'Full-time',
      remote: j.remote || false,
      company_logo: '',
      applicants: null,
      seniority: '',
      required_skills: j.tags || [],
      highlights: {}
    }));
  }

  else if (platform === 'remoteok') {
    // RemoteOK returns an array; first element is metadata, skip it
    const jobs = Array.isArray(raw) ? raw.filter(j => j.id && j.position) : [];
    jobs.forEach(j => allJobs.push({
      platform: 'RemoteOK',
      id: String(j.id) || ('ro-' + Math.random()),
      title: j.position || '',
      company: j.company || '',
      location: 'Remote',
      description: (j.description || '').substring(0, 800),
      url: j.url || `https://remoteok.com/l/${j.id}`,
      salary: j.salary_min ? `$${j.salary_min}–$${j.salary_max}` : '',
      posted_date: j.epoch ? new Date(parseInt(j.epoch) * 1000).toISOString() : '',
      job_type: 'Full-time',
      remote: true,
      company_logo: j.company_logo || '',
      applicants: j.applications || null,
      seniority: '',
      required_skills: j.tags || [],
      highlights: {}
    }));
  }

  else if (platform === 'himalayas') {
    // Himalayas.app free jobs API — returns jobs[]
    const jobs = raw.jobs || [];
    jobs.forEach(j => allJobs.push({
      platform: 'Himalayas',
      id: String(j.id) || ('hm-' + Math.random()),
      title: j.title || '',
      company: j.companyName || j.company?.name || '',
      location: j.locationRestrictions?.join(', ') || 'Remote',
      description: (j.description || '').replace(/<[^>]+>/g, '').substring(0, 800),
      url: j.applyUrl || j.url || '',
      salary: j.minSalary ? `$${Math.round(j.minSalary/1000)}K–$${Math.round(j.maxSalary/1000)}K` : '',
      posted_date: j.publishedAt || '',
      job_type: j.jobType || 'Full-time',
      remote: true,
      company_logo: j.companyLogo || '',
      applicants: null,
      seniority: j.seniority || '',
      required_skills: j.skills || [],
      highlights: {}
    }));
  }

  else if (platform === 'themuse') {
    const jobs = raw.results || [];
    jobs.forEach(j => allJobs.push({
      platform: 'The Muse',
      id: String(j.id) || ('tm-' + Math.random()),
      title: j.name || '',
      company: j.company?.name || '',
      location: (j.locations || []).map(l => l.name).join(', ') || 'Remote',
      description: (j.contents || '').replace(/<[^>]+>/g, '').substring(0, 800),
      url: j.refs?.landing_page || '',
      salary: '',
      posted_date: j.publication_date || '',
      job_type: (j.levels || []).map(l => l.name).join(', ') || 'Full-time',
      remote: (j.locations || []).some(l => l.name.toLowerCase().includes('remote')),
      company_logo: j.company?.refs?.logo_image || '',
      applicants: null,
      seniority: (j.levels || []).map(l => l.name).join(', '),
      required_skills: [],
      highlights: {}
    }));
  }

} catch(err) {
  console.log(`[${platform}] Normalize error:`, err.message);
}

// Attach searchConfig to each job for downstream use
return allJobs.map(job => ({
  json: {
    ...job,
    searchConfig,
    resumeData: $json.resumeData,
    requestId: $json.requestId,
    userPreferences: $json.userPreferences
  }
}));

// Collect all normalized jobs from all branches
// All items are already merged by the Merge node
const allItems = $input.all();
const allJobs = allItems.map(i => i.json).filter(j => j.title && j.company);

// Grab shared context from first item
const resumeData = allItems[0]?.json?.resumeData || {};
const searchConfig = allItems[0]?.json?.searchConfig || {};
const userPreferences = allItems[0]?.json?.userPreferences || {};
const requestId = allItems[0]?.json?.requestId || ('job-' + Date.now());

// Heuristic pre-scoring
const candidateSkills = (resumeData.skills?.technical || []).map(s => s.toLowerCase());
const candidateTitles = (searchConfig.titles || []).map(t => t.toLowerCase());
const prefersRemote = (searchConfig.locations || []).some(l => l.toLowerCase().includes('remote'));

const scoredJobs = allJobs.map(job => {
  let score = 0;
  const title = (job.title || '').toLowerCase();
  const desc = (job.description || '').toLowerCase();
  const reqSkills = (job.required_skills || []).map(s => s.toLowerCase());

  candidateTitles.forEach(t => { if (title.includes(t)) score += 10; });
  candidateSkills.forEach(s => {
    if (desc.includes(s) || title.includes(s) || reqSkills.includes(s)) score += 3;
  });
  if (prefersRemote && job.remote) score += 8;
  if (job.posted_date && new Date(job.posted_date) > new Date(Date.now() - 7 * 86400000)) score += 5;

  return { ...job, heuristicScore: score };
});

// Deduplicate by title+company, sort by heuristic, take top 40
const seen = new Set();
const deduped = scoredJobs
  .sort((a, b) => b.heuristicScore - a.heuristicScore)
  .filter(job => {
    const key = (job.title + '|' + job.company).toLowerCase().replace(/\s+/g, '');
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .slice(0, 40)
  .map(({ heuristicScore, ...j }) => j);

return [{
  json: {
    aggregatedJobs: deduped,
    totalRaw: allJobs.length,
    resumeData,
    searchConfig,
    userPreferences,
    requestId
  }
}];

// $json.text = raw AI score JSON from chainLlm
// $json.aggregatedJobs, $json.resumeData etc. are passed through by chainLlm
const rawScores = $json.text || '[]';
const aggregatedJobs = $json.aggregatedJobs || [];

let scoreMap = {};
try {
  let cleaned = rawScores.trim();
  const s = cleaned.indexOf('[');
  const e = cleaned.lastIndexOf(']');
  if (s !== -1 && e !== -1) cleaned = cleaned.substring(s, e + 1);
  const scores = JSON.parse(cleaned);
  scores.forEach(sc => { scoreMap[sc.job_id] = sc; });
} catch(err) {
  console.log('Score parse error:', err.message, '| First 200 chars:', rawScores.substring(0, 200));
}

// Merge AI scores into job objects
const scoredJobs = aggregatedJobs.map(job => {
  const sc = scoreMap[job.id] || {};
  return {
    ...job,
    match_score: sc.match_score || 0,
    match_reasons: sc.match_reasons || [],
    missing_skills: sc.missing_skills || [],
    strengths: sc.strengths || [],
    application_priority: sc.application_priority || 'low',
    cover_letter_angle: sc.cover_letter_angle || '',
    red_flags: sc.red_flags || []
  };
});

const sorted = scoredJobs.sort((a, b) => b.match_score - a.match_score);

const highPriority   = sorted.filter(j => j.application_priority === 'high').slice(0, 10);
const mediumPriority = sorted.filter(j => j.application_priority === 'medium').slice(0, 15);
const lowPriority    = sorted.filter(j => j.application_priority === 'low').slice(0, 10);

const platforms = [...new Set(sorted.map(j => j.platform))];
const scores = sorted.slice(0, 20).map(j => j.match_score);
const avgScore = scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;

return [{
  json: {
    jobs: { high_priority: highPriority, medium_priority: mediumPriority, low_priority: lowPriority },
    stats: {
      total_found: sorted.length,
      total_raw: $json.totalRaw || 0,
      high_priority: highPriority.length,
      medium_priority: mediumPriority.length,
      low_priority: lowPriority.length,
      avg_match_score: avgScore,
      platforms_searched: platforms
    },
    resumeData: $json.resumeData,
    searchConfig: $json.searchConfig,
    requestId: $json.requestId
  }
}];

