// $json.text = career strategy JSON from chainLlm
// All other fields ($json.jobs, $json.stats, etc.) passed through
const rawStrategy = $json.text || '{}';

let careerStrategy = {};
try {
  let cleaned = rawStrategy.trim();
  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');
  if (s !== -1 && e !== -1) cleaned = cleaned.substring(s, e + 1);
  careerStrategy = JSON.parse(cleaned);
} catch(err) {
  careerStrategy = { executive_summary: 'Strategy generation error: ' + err.message };
}

const jobs = $json.jobs || {};
const stats = $json.stats || {};

const finalOutput = {
  success: true,
  request_id: $json.requestId,
  generated_at: new Date().toISOString(),
  candidate: $json.resumeData?.candidate || {},
  search_stats: stats,
  career_strategy: careerStrategy,
  jobs: {
    high_priority: (jobs.high_priority || []).map(j => ({
      id: j.id, platform: j.platform, title: j.title, company: j.company,
      location: j.location, salary: j.salary, remote: j.remote, url: j.url,
      posted_date: j.posted_date, match_score: j.match_score,
      match_reasons: j.match_reasons, missing_skills: j.missing_skills,
      strengths: j.strengths, application_priority: j.application_priority,
      cover_letter_angle: j.cover_letter_angle, red_flags: j.red_flags,
      description_excerpt: (j.description || '').substring(0, 300)
    })),
    medium_priority: (jobs.medium_priority || []).map(j => ({
      id: j.id, platform: j.platform, title: j.title, company: j.company,
      location: j.location, url: j.url, match_score: j.match_score,
      application_priority: j.application_priority, cover_letter_angle: j.cover_letter_angle
    })),
    total_found: stats.total_found || 0
  },
  meta: {
    platforms_searched: stats.platforms_searched || [],
    primary_search_query: $json.searchConfig?.primaryQuery || '',
    note: 'Results powered by Claude AI matching'
  }
};

return [{ json: finalOutput }];

// ✅ Job hunt complete! Results are in $json
// Open the execution output panel to see all matched jobs and career strategy.
const r = $input.first().json;

console.log('╔══════════════════════════════════════╗');
console.log('║     KRISH RATHI — JOB HUNT RESULTS  ║');
console.log('╚══════════════════════════════════════╝');
console.log('Total jobs found   :', r.search_stats?.total_found);
console.log('High priority      :', r.search_stats?.high_priority);
console.log('Medium priority    :', r.search_stats?.medium_priority);
console.log('Avg match score    :', r.search_stats?.avg_match_score + '%');
console.log('Platforms searched :', (r.meta?.platforms_searched || []).join(', '));
console.log('─────────────────────────────────────────');
(r.jobs?.high_priority || []).forEach((j, i) => {
  console.log(`#${i+1} [${j.match_score}%] ${j.title} @ ${j.company} (${j.platform})`);
  console.log(`    → ${j.url}`);
});
console.log('─────────────────────────────────────────');
console.log('Career Strategy:', r.career_strategy?.executive_summary);

return [{ json: r }];

const r = $input.first().json;
console.log('No high-priority matches found.');
console.log('Medium priority jobs available:', r.search_stats?.medium_priority);
console.log('Consider broadening: add more locations, adjust job titles, or expand platforms.');
return [{ json: { ...r, note: 'No high-priority matches. Medium priority jobs still available. Try broadening search.' } }];

const err = $input.first().json;
console.error('WORKFLOW ERROR:', JSON.stringify(err, null, 2));
return [{ json: {
  error: true,
  message: err.error?.message || 'Unknown error',
  node: err.execution?.lastNodeExecuted || 'unknown',
  timestamp: new Date().toISOString()
}}];

